// 原型与宿主 JSON 同源；原型更新流程是受控状态示意，不连接网络、不安装程序。
(() => {
  const locales=window.IEDITOR_RESOURCES, palettes=window.IEDITOR_PALETTES;
  const flat=(obj,prefix='',result={})=>{for(const [key,value] of Object.entries(obj)){const path=prefix?prefix+'.'+key:key;if(value&&typeof value==='object')flat(value,path,result);else result[path]=value;}return result;};
  const source=flat(locales['zh-CN']); const inverse=new Map(Object.entries(source).map(([key,value])=>[value,key]));
  const aliases={'1 寸':'1寸','2 寸':'2寸','小 2 寸':'小2寸','工作台 /':'工作台 /','原图对比（按住）':'原图对比','图像工作台':'智能图像工作台'};
  let state={language:'zh-CN',mode:'Light',palette:'DotNet'},update='idle';
  try { state={...state,...JSON.parse(localStorage.getItem('ieditor.prototype')||'{}')}; } catch {}
  if(new URLSearchParams(location.search).has('capture'))document.body.dataset.capture='true';
  const t=key=>flat(locales[state.language])[key]??source[key]??key;
  const key=short=>'Localization.'+short;
  function renderQuality(){const status=document.querySelector('#stFmt'),quality=document.querySelector('#qRange');if(!status||!quality)return;const format=document.querySelector('#fmtSeg .on')?.dataset.value?.toUpperCase()||'JPG';const size=Math.round(Number(quality.value)*0.94);status.textContent=t(key('PhotoStudio.Summary.FormatQuality')).replace('{0}',format).replace('{1}',quality.value).replace('{2}',t(key('PhotoStudio.Summary.ApproximateSize')).replace('{0:0}',size));}
  document.querySelector('#qRange')?.addEventListener('input',renderQuality);
  document.querySelector('#fmtSeg')?.addEventListener('segchange',renderQuality);
  const nodes=[],attrs=[];
  function register(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.parentElement?.closest('script,style,svg')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let node;while(node=walker.nextNode()){const original=node.textContent,trimmed=original.trim(),normalized=aliases[trimmed]??trimmed;const resource=inverse.get(normalized);if(resource)nodes.push({node,resource,before:original.slice(0,original.indexOf(trimmed)),after:original.slice(original.indexOf(trimmed)+trimmed.length)});}root.querySelectorAll('[title],[placeholder]').forEach(el=>['title','placeholder'].forEach(attribute=>{const resource=inverse.get(el.getAttribute(attribute));if(resource)attrs.push({el,attribute,resource});}));}
  const tools=document.createElement('div');tools.className='product-tools';tools.innerHTML='<select data-mode aria-label="Theme"></select><select data-palette aria-label="Palette"></select><select data-language aria-label="Language"><option value="zh-CN">简体中文</option><option value="en-US">English</option></select>';
  document.querySelector('.titlebar')?.insertBefore(tools,document.querySelector('.win-controls'));
  document.querySelectorAll('[data-mode]').forEach(select=>{for(const mode of ['Light','Dark','System'])select.add(new Option(mode,mode));select.addEventListener('change',()=>set({mode:select.value}));});
  document.querySelectorAll('[data-palette]').forEach(select=>{for(const palette of Object.keys(palettes))select.add(new Option(palette,palette));select.addEventListener('change',()=>set({palette:select.value}));});
  document.querySelectorAll('[data-language]').forEach(select=>select.addEventListener('change',()=>set({language:select.value})));
  const swatches=document.querySelector('[data-palettes]');if(swatches)for(const palette of Object.keys(palettes)){const button=document.createElement('button');button.type='button';button.className='swatch';button.dataset.paletteKey=palette;button.style.background=palettes[palette].Light.StudioAccentColor;button.addEventListener('click',()=>set({palette}));swatches.append(button);}
  document.addEventListener('segchange',event=>{if(['light','dark','system'].includes(event.detail.value))set({mode:event.detail.value[0].toUpperCase()+event.detail.value.slice(1)});});
  document.querySelectorAll('.menu-entry').forEach(entry=>{const text=entry.textContent.trim();if(text.includes('关于 IEditor')){entry.classList.remove('disabled');entry.addEventListener('click',event=>{event.preventDefault();about.showModal();});}if(text.includes('检查更新'))entry.addEventListener('click',event=>{event.preventDefault();about.showModal();advance();});});
  const about=document.createElement('dialog');about.className='product-about';about.innerHTML=`<header class="about-titlebar"><b data-i18n="About.Text.Title"></b><div><button data-about-min>−</button><button data-about-max>□</button><button class="about-close" data-close>×</button></div></header><div class="about-heading"><img src="../logo.png" alt="IEditor"><div><h2>IEditor</h2><div data-i18n="About.Text.Description"></div></div></div><dl class="about-meta"><dt data-i18n="About.Text.Version"></dt><dd>v0.3.7</dd><dt data-i18n="About.Text.CompileTime"></dt><dd>2026-10-15 00:00:00</dd><dt data-i18n="About.Text.Platform"></dt><dd>.NET 10 · Avalonia 12.1.4</dd><dt data-i18n="About.Text.Author"></dt><dd>dotnet9</dd></dl><a href="https://github.com/dotnet9/IEditor" class="btn" data-i18n="About.Text.Repository"></a><div class="about-update"><p data-i18n="About.Text.UpdateDescription"></p><button class="btn primary" data-update-action></button><button class="btn" data-update-cancel data-i18n="About.Text.Cancel" hidden></button><p role="status" data-update-status></p></div><p data-i18n="About.Text.Copyright"></p>`;document.body.append(about);about.querySelector('[data-close]').onclick=()=>about.close();about.querySelector('[data-about-min]').onclick=()=>about.close();about.querySelector('[data-about-max]').onclick=()=>about.classList.toggle('about-maximized');about.querySelector('[data-update-action]').onclick=advance;about.querySelector('[data-update-cancel]').onclick=()=>{update='canceled';renderUpdate();};
  function advance(){update=({idle:'checking',checking:'available',available:'downloading',downloading:'downloaded',downloaded:'installed',installed:'checking',canceled:'checking',failed:'checking'})[update];renderUpdate();}
  function renderUpdate(){const labels={idle:'Check',checking:'Checking',available:'Download',downloading:'Downloading',downloaded:'Install',installed:'Check',canceled:'Check',failed:'Check'};about.querySelector('[data-update-action]').textContent=t(key('About.Text.'+labels[update]));about.querySelector('[data-update-cancel]').hidden=!['checking','downloading'].includes(update);about.querySelector('[data-update-status]').textContent=update==='idle'?'':update==='installed'?t(key('About.Text.Downloaded')):t(key('About.Text.'+({checking:'Checking',available:'Available',downloading:'Downloading',downloaded:'Downloaded',canceled:'Canceled',failed:'Failed'})[update])).replace('{0}','0.3.7');}
  function set(change){Object.assign(state,change);localStorage.setItem('ieditor.prototype',JSON.stringify(state));render();}
  function render(){const dark=state.mode==='Dark'||(state.mode==='System'&&matchMedia('(prefers-color-scheme: dark)').matches);const token=palettes[state.palette][dark?'Dark':'Light'];const css={'--bg':'StudioBackgroundColor','--surface':'StudioSurfaceColor','--surface-2':'StudioRaisedColor','--border':'StudioBorderColor','--border-strong':'StudioBorderColor','--text-1':'StudioTextColor','--text-2':'StudioMutedColor','--text-3':'StudioMutedColor','--primary':'StudioAccentColor','--cyan':'StudioSecondaryColor'};for(const [name,value]of Object.entries(css))document.documentElement.style.setProperty(name,token[value]);document.documentElement.style.setProperty('--grad',`linear-gradient(135deg,${token.StudioAccentColor},${token.StudioSecondaryColor})`);document.body.dataset.theme=dark?'dark':'light';document.documentElement.lang=state.language;
    for(const item of nodes)item.node.textContent=item.before+t(item.resource)+item.after;for(const item of attrs)item.el.setAttribute(item.attribute,t(item.resource));document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(key(el.dataset.i18n)));
    document.querySelectorAll('[data-mode]').forEach(select=>{[...select.options].forEach(option=>option.textContent=t(key('Common.Theme.'+option.value)));select.value=state.mode;});document.querySelectorAll('[data-palette]').forEach(select=>{[...select.options].forEach(option=>option.textContent=t(key('Settings.Options.'+option.value)));select.value=state.palette;});document.querySelectorAll('[data-language]').forEach(select=>select.value=state.language);document.querySelectorAll('[data-palette-key]').forEach(button=>{button.classList.toggle('on',button.dataset.paletteKey===state.palette);button.title=t(key('Settings.Options.'+button.dataset.paletteKey));});renderQuality();renderUpdate();}
  register(document.body);render();
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>render());
  window.IEditorPrototype={set,getState:()=>({...state}),openAbout:()=>about.showModal(),setUpdate:value=>{update=value;renderUpdate();}};
})();
